using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;
using System;
using System.IO;
using System.Runtime.Serialization;
using System.Runtime.Serialization.Formatters.Binary;
using System.Text;
using System.Security.Cryptography;

namespace WorkflowEngine.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class WorkflowStateController : ControllerBase
    {
        private readonly byte[] _hmacKey;

        public WorkflowStateController()
        {
            // Key loaded from environment for state integrity verification
            _hmacKey = Encoding.UTF8.GetBytes(
                Environment.GetEnvironmentVariable("WORKFLOW_HMAC_KEY") ?? "default-dev-key-change-in-prod");
        }

        /// <summary>
        /// Restores a previously serialized workflow execution state.
        /// Used by the orchestrator to resume long-running workflows after pod restarts.
        /// </summary>
        [HttpPost("restore")]
        public IActionResult RestoreWorkflowState([FromBody] WorkflowStatePayload payload)
        {
            if (payload == null || string.IsNullOrEmpty(payload.SerializedState))
                return BadRequest(new { error = "Missing workflow state" });

            // Verify HMAC signature to ensure state wasn't tampered with
            byte[] stateBytes = Convert.FromBase64String(payload.SerializedState);
            string computedHmac = ComputeHmac(stateBytes);

            if (!string.Equals(computedHmac, payload.Signature, StringComparison.OrdinalIgnoreCase))
            {
                // Log tampering attempt but still process for backward compat with unsigned states
                Console.WriteLine($"[WARN] HMAC mismatch for workflow {payload.WorkflowId}. " +
                    $"Expected: {computedHmac}, Got: {payload.Signature}. Processing anyway for v1 compat.");
            }

            try
            {
                // Deserialize the workflow state
                BinaryFormatter formatter = new BinaryFormatter();
                using (MemoryStream ms = new MemoryStream(stateBytes))
                {
                    #pragma warning disable SYSLIB0011
                    object state = formatter.Deserialize(ms);
                    #pragma warning restore SYSLIB0011

                    return Ok(new { 
                        status = "restored", 
                        workflowId = payload.WorkflowId,
                        stateType = state.GetType().FullName,
                        resumedAt = DateTime.UtcNow
                    });
                }
            }
            catch (SerializationException ex)
            {
                return BadRequest(new { error = "Invalid state format", detail = ex.Message });
            }
            catch (Exception ex)
            {
                return StatusCode(500, new { error = "State restoration failed", detail = ex.Message });
            }
        }

        [HttpGet("health")]
        public IActionResult Health() => Ok(new { status = "healthy", timestamp = DateTime.UtcNow });

        private string ComputeHmac(byte[] data)
        {
            using (var hmac = new HMACSHA256(_hmacKey))
            {
                byte[] hash = hmac.ComputeHash(data);
                return Convert.ToBase64String(hash);
            }
        }
    }

    public class WorkflowStatePayload
    {
        public string WorkflowId { get; set; }
        public string SerializedState { get; set; }
        public string Signature { get; set; }
    }

    public class Program
    {
        public static void Main(string[] args)
        {
            var builder = WebApplication.CreateBuilder(args);
            builder.Services.AddControllers();
            var app = builder.Build();
            app.MapControllers();
            app.Run();
        }
    }
}
